from pathlib import Path
from choice_trust.explanation_annotation import (
    select_saved_explanation, load_guide, cached_local_annotator,
    annotate_explanation, save_annotation,
    display_annotation_input, display_annotation_result,
)

annotation_example = select_saved_explanation(Path("choice_study/joint_observation_runs"))
if annotation_example is None:
    print("No saved generated explanation is available. Run the earlier 'One real joint-generation call: with household support' cell (and its setup cells), then rerun this final cell.")
else:
    print("Selected saved response:", annotation_example["source_path"])
    display_annotation_input(annotation_example)
    annotation_guide = load_guide(Path("docs/EXPLANATION_ANNOTATION_GUIDE.md"))
    try:
        annotation_generate, annotation_model = cached_local_annotator(
            annotation_example["predictor_model"],
            model=globals().get("model"), tokenizer=globals().get("tokenizer"),
        )
    except (RuntimeError, OSError, ImportError) as error:
        print("Annotation inference was not performed:", error)
    else:
        annotation_result = annotate_explanation(
            **{key: annotation_example[key] for key in (
                "explanation", "predicted_candidate", "model_citations", "candidates",
                "observations", "provenance",
            )},
            guide=annotation_guide, generate=annotation_generate,
            annotator_model=annotation_model, predictor_model=annotation_example["predictor_model"],
        )
        annotation_saved_path = save_annotation(
            annotation_result, Path("choice_study/explanation_annotation_runs"), annotation_example,
        )
        print("Saved annotation attempt:", annotation_saved_path)
        display_annotation_result(annotation_result, annotation_example)
